0\\\\n        n_batches = 0\\\\n\\\\n        for batch_idx, batch in enumerate(train_loader):\\\\n            obs_feat = batch[\\\\\\\"obs_features\\\\\\\"].to(device)       # (B, 960)\\\\n            k_samp = batch[\\\\\\\"k_samples\\\\\\\"].to(device)             # (B, K, H, D)\\\\n            expert = batch[\\\\\\\"expert_action\\\\\\\"].to(device)         # (B, H, D)\\\\n            expert_flat = expert.reshape(expert.shape[0], -1)  # (B, 30)\\\\n\\\\n            # CGS\\\\n            uf, ma = cgs.compute_features_batch(k_samp)\\\\n            uf = uf.to(device)\\\\n            ma = ma.to(device)\\\\n\\\\n            # CRM forward\\\\n            refined = crm(ma, uf, obs_feat)\\\\n            loss = loss_fn(refined, expert_flat)\\\\n\\\\n            # Synthetic augmentation: perturb inputs, keep clean target\\\\n            n_aug = int(obs_feat.shape[0] * args.aug_ratio)\\\\n            if n_aug > 0:\\\\n                ma_noise = noise_scale.repeat(H_EFF)\\\\n                aug_ma = ma[:n_aug] + torch.randn_like(ma[:n_aug]) * ma_noise\\\\n                aug_uf = uf[:n_aug] + torch.randn_like(uf[:n_aug]) * noise_scale.mean() * 0.1\\\\n                aug_refined = crm(aug_ma, aug_uf, obs_feat[:n_aug])\\\\n                aug_loss = loss_fn(aug_refined, expert_flat[:n_aug])\\\\n                loss = loss + 0.5 * aug_loss\\\\n\\\\n            optimizer.zero_grad()\\\\n            loss.backward()\\\\n            torch.nn.utils.clip_grad_norm_(crm.parameters(), 1.0)\\\\n            optimizer.step()\\\\n\\\\n            epoch_loss += loss.item()\\\\n            n_batches += 1\\\\n\\\\n            if (batch_idx + 1) % args.log_every == 0:\\\\n                print(f\\\\\\\"  epoch {epoch} batch {batch_idx+1}/{len(train_loader)} \\\\\\\"\\\\n                      f\\\\\\\"loss={loss.item():.6f}\\\\\\\")\\\\n\\\\n        scheduler.step()\\\\n        avg_train_loss = epoch_loss / max(n_batches, 1)\\\\n\\\\n        # ── Validate ──\\\\n        crm.eval()\\\\n        val_loss = 0.0\\\\n        n_val_batches = 0\\\\n        with torch.no_grad():\\\\n            for batch in val_loader:\\\\n                obs_feat = batch[\\\\\\\"obs_features\\\\\\\"].to(device)\\\\n                k_samp = batch[\\\\\\\"k_samples\\\\\\\"].to(device)\\\\n                expert = batch[\\\\\\\"expert_action\\\\\\\"].to(device)\\\\n                expert_flat = expert.reshape(expert.shape[0], -1)\\\\n\\\\n                uf, ma = cgs.compute_features_batch(k_samp)\\\\n                uf, ma = uf.to(device), ma.to(device)\\\\n\\\\n                refined = crm(ma, uf, obs_feat)\\\\n                val_loss += loss_fn(refined, expert_flat).item()\\\\n                n_val_batches += 1\\\\n\\\\n        avg_val_loss = val_loss / max(n_val_batches, 1)\\\\n\\\\n        print(f\\\\\\\"Epoch {epoch}/{args.epochs}  \\\\\\\"\\\\n              f\\\\\\\"train_loss={avg_train_loss:.6f}  \\\\\\\"\\\\n              f\\\\\\\"val_loss={avg_val_loss:.6f}  \\\\\\\"\\\\n              f\\\\\\\"lr={scheduler.get_last_lr()[0]:.2e}\\\\\\\")\\\\n\\\\n        metrics = {\\\\\\\"train_loss\\\\\\\": avg_train_loss, \\\\\\\"val_loss\\\\\\\": avg_val_loss}\\\\n        ckpt_mgr.save(crm, optimizer, epoch, metrics)\\\\n\\\\n        if avg_val_loss < best_val_loss:\\\\n            best_val_loss = avg_val_loss\\\\n            torch.save(crm.state_dict(),\\\\n                       Path(args.output_dir) / \\\\\\\"crm_best.pt\\\\\\\")\\\\n            print(f\\\\\\\"  → New best val_loss: {best_val_loss:.6f}\\\\\\\")\\\\n\\\\n    print(f\\\\\\\"\\\\\\\\n[train] Done. Best val_loss={best_val_loss:.6f}\\\\\\\")\\\\n    print(f\\\\\\\"[train] Checkpoints at {args.output_dir}\\\\\\\")\\\\n\\\\n\\\\ndef main():\\\\n    args = parse_args()\\\\n    print(f\\\\\\\"[train_crm] args: {vars(args)}\\\\\\\")\\\\n    print(f\\\\\\\"[train_crm] device: {'cuda' if torch.cuda.is_available() else 'cpu'}\\\\\\\")\\\\n\\\\n    if args.precompute:\\\\n        precompute_features(args)\\\\n        return\\\\n\\\\n    if args.auto:\\\\n        needs_precompute = any(\\\\n            not (Path(args.cache_dir) / bm / \\\\\\\"manifest.json\\\\\\\").exists()\\\\n            for bm in args.benchmark\\\\n        )\\\\n        if needs_precompute:\\\\n            print(\\\\\\\"[auto] Cache not found for some benchmarks, precomputing...\\\\\\\")\\\\n            precompute_features(args)\\\\n\\\\n    train(args)\\\\n\\\\n\\\\nif __name__ == \\\\\\\"__main__\\\\\\\":\\\\n    main()\\\\n\\\", \\\"stderr\\\": \\\"\\\", \\\"return_code\\\": 0}, \\\"error\\\": null, \\\"metadata\\\": {\\\"elapsed_seconds\\\": 0.83}}\"}","structuredContent":{"result":"{\"success\": true, \"data\": {\"stdout\": \"\\\"\\\"\\\"\\nCRM training script.\\n\\nTwo-phase approach:\\n  Phase 1 (--precompute): Run frozen SmolVLA on LIBERO demos, cache\\n      (obs_features, K_samples, expert_action) to disk.\\n  Phase 2 (default): Load cached features, train CRM with MSE loss +\\n      synthetic augmentation.\\n\\nUsage:\\n  # Phase 1: precompute features (slow, GPU-heavy)\\n  python train_crm.py --precompute --benchmark object\\n\\n  # Phase 2: train CRM (fast)\\n  python train_crm.py --benchmark object --epochs 50\\n\\n  # End-to-end (precompute if cache missing, then train)\\n  python train_crm.py --benchmark object --epochs 50 --auto\\n\\\"\\\"\\\"\\nimport argparse\\nimport os\\nimport sys\\nimport json\\nimport time\\nfrom pathlib import Path\\n\\nimport torch\\nimport torch.nn as nn\\nfrom torch.utils.data import Dataset, DataLoader\\nimport numpy as np\\n\\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\\nfrom cgs import ConformilizedGaussianScoring\\nfrom crm import ConformalRefinementModule\\nfrom utils import (\\n    set_seed, load_libero_demos, build_training_samples,\\n    synthetic_augmentation, CheckpointManager,\\n    ACTION_DIM, H_EFF, OBS_DIM, CHUNK_SIZE,\\n)\\n\\n\\ndef parse_args():\\n    p = argparse.ArgumentParser(description=\\\"Train CRM on LIBERO demos\\\")\\n    p.add_argument(\\\"--benchmark\\\", type=str, nargs='+', default=[\\\"spatial\\\"],\\n                   choices=[\\\"object\\\", \\\"spatial\\\", \\\"goal\\\", \\\"long\\\", \\\"90\\\"])\\n    p.add_argument(\\\"--epochs\\\", type=int, default=50)\\n    p.add_argument(\\\"--batch_size\\\", type=int, default=32)\\n    p.add_argument(\\\"--lr\\\", type=float, default=1e-3)\\n    p.add_argument(\\\"--seed\\\", type=int, default=42)\\n    p.add_argument(\\\"--output_dir\\\", type=str,\\n                   default=\\\"/root/autodl-tmp/checkpoints/crm/\\\")\\n    p.add_argument(\\\"--cache_dir\\\", type=str,\\n                   default=\\\"/root/autodl-tmp/crm_cache/\\\")\\n    p.add_argument(\\\"--K\\\", type=int, default=10)\\n    p.add_argument(\\\"--obs_dim\\\", type=int, default=OBS_DIM)\\n    p.add_argument(\\\"--hidden_dim\\\", type=int, default=256)\\n    p.add_argument(\\\"--aug_noise_min\\\", type=float, default=0.02)\\n    p.add_argument(\\\"--aug_noise_max\\\", type=float, default=0.1)\\n    p.add_argument(\\\"--aug_ratio\\\", type=float, default=0.5,\\n                   help=\\\"fraction of batch to augment\\\")\\n    p.add_argument(\\\"--precompute\\\", action=\\\"store_true\\\",\\n                   help=\\\"only precompute features, don't train\\\")\\n    p.add_argument(\\\"--auto\\\", action=\\\"store_true\\\",\\n                   help=\\\"precompute if cache missing, then train\\\")\\n    p.add_argument(\\\"--smolvla_path\\\", type=str, default=\\\"lerobot/smolvla_base\\\")\\n    p.add_argument(\\\"--max_demos_per_task\\\", type=int, default=50)\\n    p.add_argument(\\\"--val_split\\\", type=float, default=0.1)\\n    p.add_argument(\\\"--log_every\\\", type=int, default=50)\\n    return p.parse_args()\\n\\n\\n# ── Precomputation ──────────────────────────────────────────────────\\n\\ndef precompute_features(args):\\n    \\\"\\\"\\\"Run frozen SmolVLA on all demo timesteps, save features to disk.\\\"\\\"\\\"\\n    from smolvla_wrapper import SmolVLAWrapper\\n\\n    benchmarks_to_run = []\\n    for bm in args.benchmark:\\n        cache_dir = Path(args.cache_dir) / bm\\n        if (cache_dir / \\\"manifest.json\\\").exists():\\n            print(f\\\"[precompute] Cache exists at {cache_dir}, skipping {bm}.\\\")\\n        else:\\n            benchmarks_to_run.append(bm)\\n\\n    if not benchmarks_to_run:\\n        return\\n\\n    print(f\\\"[precompute] Loading SmolVLA from {args.smolvla_path}...\\\")\\n    wrapper = SmolVLAWrapper(args.smolvla_path, device=\\\"cuda\\\")\\n    print(f\\\"[precompute] VLM hidden_size = {wrapper.vlm_hidden_size}\\\")\\n\\n    for benchmark in benchmarks_to_run:\\n        cache_dir = Path(args.cache_dir) / benchmark\\n        cache_dir.mkdir(parents=True, exist_ok=True)\\n\\n        print(f\\\"[precompute] Loading LIBERO demos ({benchmark})...\\\")\\n        trajectories = load_libero_demos(benchmark,\\n                                         max_demos_per_task=args.max_demos_per_task)\\n        samples = build_training_samples(trajectories)\\n        print(f\\\"[precompute] {len(samples)} training samples from \\\"\\n              f\\\"{len(trajectories)} trajectories.\\\")\\n\\n       \\n\\n... [截断: 输出过长，省略 5610 字符] ...\\n\\nmax_keep=5)\\n\\n    noise_scale = torch.linspace(\\n        args.aug_noise_min, args.aug_noise_max, ACTION_DIM\\n    ).to(device)\\n\\n    best_val_loss = float(\\\"inf\\\")\\n\\n    for epoch in range(1, args.epochs + 1):\\n        # ── Train ──\\n        crm.train()\\n        epoch_loss = 0.0\\n        n_batches = 0\\n\\n        for batch_idx, batch in enumerate(train_loader):\\n            obs_feat = batch[\\\"obs_features\\\"].to(device)       # (B, 960)\\n            k_samp = batch[\\\"k_samples\\\"].to(device)             # (B, K, H, D)\\n            expert = batch[\\\"expert_action\\\"].to(device)         # (B, H, D)\\n            expert_flat = expert.reshape(expert.shape[0], -1)  # (B, 30)\\n\\n            # CGS\\n            uf, ma = cgs.compute_features_batch(k_samp)\\n            uf = uf.to(device)\\n            ma = ma.to(device)\\n\\n            # CRM forward\\n            refined = crm(ma, uf, obs_feat)\\n            loss = loss_fn(refined, expert_flat)\\n\\n            # Synthetic augmentation: perturb inputs, keep clean target\\n            n_aug = int(obs_feat.shape[0] * args.aug_ratio)\\n            if n_aug > 0:\\n                ma_noise = noise_scale.repeat(H_EFF)\\n                aug_ma = ma[:n_aug] + torch.randn_like(ma[:n_aug]) * ma_noise\\n                aug_uf = uf[:n_aug] + torch.randn_like(uf[:n_aug]) * noise_scale.mean() * 0.1\\n                aug_refined = crm(aug_ma, aug_uf, obs_feat[:n_aug])\\n                aug_loss = loss_fn(aug_refined, expert_flat[:n_aug])\\n                loss = loss + 0.5 * aug_loss\\n\\n            optimizer.zero_grad()\\n            loss.backward()\\n            torch.nn.utils.clip_grad_norm_(crm.parameters(), 1.0)\\n            optimizer.step()\\n\\n            epoch_loss += loss.item()\\n            n_batches += 1\\n\\n            if (batch_idx + 1) % args.log_every == 0:\\n                print(f\\\"  epoch {epoch} batch {batch_idx+1}/{len(train_loader)} \\\"\\n                      f\\\"loss={loss.item():.6f}\\\")\\n\\n        scheduler.step()\\n        avg_train_loss = epoch_loss / max(n_batches, 1)\\n\\n        # ── Validate ──\\n        crm.eval()\\n        val_loss = 0.0\\n        n_val_batches = 0\\n        with torch.no_grad():\\n            for batch in val_loader:\\n                obs_feat = batch[\\\"obs_features\\\"].to(device)\\n                k_samp = batch[\\\"k_samples\\\"].to(device)\\n                expert = batch[\\\"expert_action\\\"].to(device)\\n                expert_flat = expert.reshape(expert.shape[0], -1)\\n\\n                uf, ma = cgs.compute_features_batch(k_samp)\\n                uf, ma = uf.to(device), ma.to(device)\\n\\n                refined = crm(ma, uf, obs_feat)\\n                val_loss += loss_fn(refined, expert_flat).item()\\n                n_val_batches += 1\\n\\n        avg_val_loss = val_loss / max(n_val_batches, 1)\\n\\n        print(f\\\"Epoch {epoch}/{args.epochs}  \\\"\\n              f\\\"train_loss={avg_train_loss:.6f}  \\\"\\n              f\\\"val_loss={avg_val_loss:.6f}  \\\"\\n              f\\\"lr={scheduler.get_last_lr()[0]:.2e}\\\")\\n\\n        metrics = {\\\"train_loss\\\": avg_train_loss, \\\"val_loss\\\": avg_val_loss}\\n        ckpt_mgr.save(crm, optimizer, epoch, metrics)\\n\\n        if avg_val_loss < best_val_loss:\\n            best_val_loss = avg_val_loss\\n            torch.save(crm.state_dict(),\\n                       Path(args.output_dir) / \\\"crm_best.pt\\\")\\n            print(f\\\"  → New best val_loss: {best_val_loss:.6f}\\\")\\n\\n    print(f\\\"\\\\n[train] Done. Best val_loss={best_val_loss:.6f}\\\")\\n    print(f\\\"[train] Checkpoints at {args.output_dir}\\\")\\n\\n\\ndef main():\\n    args = parse_args()\\n    print(f\\\"[train_crm] args: {vars(args)}\\\")\\n    print(f\\\"[train_crm] device: {'cuda' if torch.cuda.is_available() else 'cpu'}\\\")\\n\\n    if args.precompute:\\n        precompute_features(args)\\n        return\\n\\n    if args.auto:\\n        needs_precompute = any(\\n            not (Path(args.cache_dir) / bm / \\\"manifest.json\\\").exists()\\n            for bm in args.benchmark\\n        )\\n        if needs_precompute:\\n            print(\\\"[auto] Cache not found for some benchmarks, precomputing...\\\")\\n            precompute_features(args)\\n\\n    train(args)\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\", \"stderr\": \"\", \"return_code\": 0}, \"error\": null, \"metadata\": {\"elapsed_seconds\": 0.83}}"}}}
{"type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_01GWTL6QMmfv7WCvYsRkqCoe","type":"tool_result","content":"{\"result\":\"{\\\"success\\\": true, \\\"data\\\": {\\\"stdout\\\": \\\"\\\\\\\"\\\\\\\"\\\\\\\"\\\\nSmolVLA wrapper for ACR-VLA.\\\\n\\\\nProvides:\\\\n  1. obs_features extraction (mean-pooled VLM hidden states, 960D)\\\\n  2. K-sample flow-matching generation with shared KV cache\\\\n  3. LIBERO data preprocessing (image, language, state → SmolVLA inputs)\\\\n\\\\\\\"\\\\\\\"\\\\\\\"\\\\nimport math\\\\nimport torch\\\\nimport torch.nn.functional as F\\\\nimport numpy as np\\\\nfrom PIL import Image\\\\nfrom torchvision import transforms as T\\\\n\\\\nfrom lerobot.policies.smolvla.modeling_smolvla import (\\\\n    SmolVLAPolicy,\\\\n    VLAFlowMatching,\\\\n    make_att_2d_masks,\\\\n    resize_with_pad,\\\\n)\\\\n\\\\n\\\\nclass SmolVLAWrapper:\\\\n    \\\\\\\"\\\\\\\"\\\\\\\"Frozen SmolVLA for obs_features and K-sample generation.\\\\\\\"\\\\\\\"\\\\\\\"\\\\n\\\\n    def __init__(self, pretrained_path: str = \\\\\\\"lerobot/smolvla_base\\\\\\\",\\\\n                 device: str = \\\\\\\"cuda\\\\\\\"):\\\\n        self.device = torch.device(device)\\\\n        self.policy = SmolVLAPolicy.from_pretrained(pretrained_path)\\\\n        self.policy.to(self.device)\\\\n        self.policy.eval()\\\\n        for p in self.policy.parameters():\\\\n            p.requires_grad = False\\\\n\\\\n        self.flow: VLAFlowMatching = self.policy.model\\\\n        self.processor = self.flow.vlm_with_expert.processor\\\\n        self.tokenizer = self.processor.tokenizer\\\\n        self.config = self.policy.config\\\\n\\\\n        self.vlm_hidden_size = self.flow.vlm_with_expert.config.text_config.hidden_size  # 960\\\\n        self.img_transform = T.Compose([\\\\n            T.ToTensor(),  # HWC uint8 → CHW float [0,1]\\\\n        ])\\\\n\\\\n    @torch.no_grad()\\\\n    def preprocess_obs(self, agentview_rgb: np.ndarray,\\\\n                    